class Solution {
    public int maximizeTheProfit(int n,List<List<Integer>> offers){
        offers.sort(Comparator.comparingInt(offer->offer.get(1)));
        int[] dp=new int[n+1];
        int index=0;
        for(int end=0;end<n;end++){
            dp[end+1]=Math.max(dp[end+1],dp[end]);
            while(index<offers.size()&&offers.get(index).get(1)==end){
                List<Integer> offer=offers.get(index++);
                dp[end+1]=Math.max(dp[end+1],dp[offer.get(0)]+offer.get(2));
            }
        }
        return dp[n];
    }
}

code.kotlin:
class Solution {
    fun maximizeTheProfit(n:Int,offers:List<List<Int>>):Int{
        val sorted=offers.sortedBy{
            it[1]
        };
        val dp=IntArray(n+1);
        var index=0;
        for(end in 0 until n){
            dp[end+1]=maxOf(dp[end+1],dp[end]);
            while(index<sorted.size&&sorted[index][1]==end){
                val offer=sorted[index++];
                dp[end+1]=maxOf(dp[end+1],dp[offer[0]]+offer[2])
            }
        };
        return dp[n]
    }
}

